        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var m = this._run(this._flat(state, mm), mm);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var d = this._flat(state, mm);
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            insights.push(this._t('fb_next'));
            var vk = this._verdictKey(composite);
            var profits = m.per.map(function(x) { return Math.round(x.profit); });
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                profit: this._sum(profits),
                net: Math.round(m.net),
                debt: Math.round(m.debt),
                cash: Math.round(m.cash),
                record: Math.round(m.hist),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore : 0;
            var items = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="ej2265-cm">'
                + '<div class="ej2265-cm-score">' + score + '<span class="ej2265-cm-max">/100</span></div>'
                + '<div class="ej2265-cm-verdict">' + (s.performanceLabel || '') + '</div>'
                + '<div class="ej2265-cm-kpis">'
                + '<div class="ej2265-cm-kpi">' + this._t('cm_kpi_profit') + ' <strong>' + this._fmtCop(s.profit || 0) + '</strong></div>'
                + '<div class="ej2265-cm-kpi">' + this._t('cm_kpi_net') + ' <strong>' + this._fmtCop(s.net || 0) + '</strong></div>'
                + '<div class="ej2265-cm-kpi">' + this._t('cm_kpi_debt') + ' <strong>' + this._fmtCop(s.debt || 0) + '</strong></div>'
                + '<div class="ej2265-cm-kpi">' + this._t('cm_kpi_cash') + ' <strong>' + this._fmtCop(s.cash || 0) + '</strong></div>'
                + '<div class="ej2265-cm-kpi">' + this._t('cm_kpi_record') + ' <strong>' + this._fmtInt(s.record || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2265-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2265-cm-insights">' + items + '</ul>'
                + '</div>';
        }

